// Authenticate a Foundry connection as an identity rather than with a stored key
resource connection 'Microsoft.CognitiveServices/accounts/projects/connections@2025-04-01-preview' = {
  parent: project
  name: '<example_connection_name>'
  properties: {
    category: '<category>'
    target: '<target_url>'
    authType: 'AAD' // CRITICAL: no key is stored in the connection
    isSharedToAll: false
  }
}
